from collections import defaultdict

def count_matching_ranges(n, numbers):
    count = 0
    prefix_sum = [0] * (n + 1)
    prefix_product = [1] * (n + 1)

    sum_dict = defaultdict(list)
    product_dict = defaultdict(list)

    for i in range(1, n + 1):
        prefix_sum[i] = prefix_sum[i - 1] + numbers[i - 1]
        prefix_product[i] = prefix_product[i - 1] * numbers[i - 1]

        if prefix_sum[i] == prefix_product[i]:
            count += 1

        if prefix_sum[i] in sum_dict:
            for start in sum_dict[prefix_sum[i]]:
                if prefix_product[i] // prefix_product[start] == prefix_sum[i] - prefix_sum[start]:
                    count += 1
        if prefix_product[i] in product_dict:
            for start in product_dict[prefix_product[i]]:
                if prefix_sum[i] // prefix_sum[start] == prefix_product[i] // prefix_product[start]:
                    count += 1

        sum_dict[prefix_sum[i]].append(i)
        product_dict[prefix_product[i]].append(i)

    return count

